import{c as a,Q as t,j as o,m as d}from"./chunks/framework.DGHXLY8X.js";const u=JSON.parse('{"title":"Selecting a hardware encoder","description":"","frontmatter":{},"headers":[],"relativePath":"operating/encoders.md","filePath":"operating/encoders.md","lastUpdated":1780987164000}'),s={name:"operating/encoders.md"};function r(n,e,c,i,p,h){return t(),o("div",null,[...e[0]||(e[0]=[d(`<h1 id="selecting-a-hardware-encoder" tabindex="-1">Selecting a hardware encoder <a class="header-anchor" href="#selecting-a-hardware-encoder" aria-label="Permalink to &quot;Selecting a hardware encoder&quot;">​</a></h1><p>This page covers what encoders are available on your system and how to control which one VideoNode uses per stream. All choices are made via the web UI or REST API. For which encoders each platform provides, see <a href="./../reference/supported-hardware">supported hardware</a>.</p><h2 id="run-the-validator" tabindex="-1">Run the validator <a class="header-anchor" href="#run-the-validator" aria-label="Permalink to &quot;Run the validator&quot;">​</a></h2><p>Before starting the pipeline, run the built-in encoder probe. It encodes a 2-second 640×480 test clip with every compiled encoder and records what works:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">videonode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> validate-encoders</span></span></code></pre></div><p>To suppress the per-probe progress and print only the summary, add <code>--quiet</code> (<code>-q</code>):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">videonode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> validate-encoders</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --quiet</span></span></code></pre></div><p>Example output on a Rockchip RK3588 board:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=== RKMPP (Rockchip Media Process Platform) - Hardware acceleration for Rockchip SoCs ===</span></span>
<span class="line"><span>Testing h264_rkmpp...</span></span>
<span class="line"><span>h264_rkmpp: ✓ WORKING</span></span>
<span class="line"><span>Testing hevc_rkmpp...</span></span>
<span class="line"><span>hevc_rkmpp: ✓ WORKING</span></span>
<span class="line"><span># ...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>=== VALIDATION SUMMARY ===</span></span>
<span class="line"><span>H.264 encoders working: 1</span></span>
<span class="line"><span>  Working: h264_rkmpp</span></span>
<span class="line"><span>H.265 encoders working: 1</span></span>
<span class="line"><span>  Working: hevc_rkmpp</span></span></code></pre></div><p>Results are written to the daemon&#39;s state and consulted whenever a stream starts. Re-run after a driver update or after installing a new ffmpeg build.</p><h2 id="what-the-validator-checks" tabindex="-1">What the validator checks <a class="header-anchor" href="#what-the-validator-checks" aria-label="Permalink to &quot;What the validator checks&quot;">​</a></h2><p>For each compiled encoder the validator runs a real ffmpeg encode of the 2-second clip and records <code>WORKING</code> only if ffmpeg exits 0 and the output file exceeds 1 KB. It applies that encoder&#39;s production rate-control settings during the probe (rkmpp uses <code>rc_mode=VBR</code>, vaapi uses <code>qp=20</code>, software uses <code>crf</code> with <code>preset=ultrafast</code>), so a backend that compiles but can&#39;t actually run on this host fails here instead of at stream start.</p><p>Hardware backends (rkmpp, vaapi) add two more probe sweeps, each gated on the device node being present: rkmpp needs <code>/proc/mpp_service/load</code>, vaapi needs <code>/dev/dri/renderD128</code>. If the node is absent, that backend&#39;s probes are skipped entirely.</p><ul><li><strong>Decoder probes</strong> feed a synthetic encoded stream through hardware decode for <code>h264</code>, <code>hevc</code>, and <code>mjpeg</code>. The mjpeg probe uses 4:2:0 on rkmpp (its decoder rejects 4:2:2) and 4:2:2 on vaapi (to catch the radeonsi VPP gap).</li><li><strong>Filter probes</strong> exercise the exact filters the canvas builder emits: scale (NV12 and BGRA output), transpose, and BGRA-on-YUV overlay. The vaapi sweep adds an alignment probe that encodes red at a height where <code>h % 16 = 8</code> and checks the decoded bottom row, catching the AMD VCN green-row defect.</li></ul><p>Each backend&#39;s working and failed decoders and filters land in the summary under <code>Hardware backends</code>.</p><p>The rate-control matrix the running encoders accept differs per backend:</p><table tabindex="0"><thead><tr><th>Mode</th><th>rkmpp</th><th>vaapi</th><th>software (libx264/libx265)</th></tr></thead><tbody><tr><td>CBR</td><td><code>rc_mode=CBR</code>, <code>b:v</code></td><td><code>rc_mode=CBR</code>, <code>b:v</code>, <code>bufsize</code></td><td><code>b:v</code>=<code>minrate</code>=<code>maxrate</code>, <code>bufsize</code></td></tr><tr><td>VBR</td><td><code>rc_mode=VBR</code>, <code>b:v</code>, <code>minrate</code>, <code>maxrate</code></td><td><code>rc_mode=VBR</code>, <code>b:v</code>, <code>maxrate</code>, <code>bufsize</code></td><td><code>b:v</code>, <code>maxrate</code>, <code>bufsize</code></td></tr><tr><td>CRF</td><td>mapped to CQP (<code>qp_init</code>)</td><td>rejected (use CQP)</td><td><code>crf</code></td></tr><tr><td>CQP</td><td><code>rc_mode=CQP</code>, <code>qp_init</code></td><td><code>rc_mode=CQP</code>, <code>qp</code></td><td><code>qp</code></td></tr></tbody></table><p>rkmpp has no CRF, so a CRF request is carried as CQP through <code>qp_init</code>. vaapi rejects CRF outright and returns an error telling you to use CQP.</p><h2 id="how-videonode-picks-an-encoder" tabindex="-1">How VideoNode picks an encoder <a class="header-anchor" href="#how-videonode-picks-an-encoder" aria-label="Permalink to &quot;How VideoNode picks an encoder&quot;">​</a></h2><p>When a stream starts, VideoNode selects the concrete ffmpeg encoder from the saved validation results. If no validation data exists, it falls back to software: <code>libx264</code> for H.264 and <code>libx265</code> for H.265. This fallback does not probe <code>ffmpeg -encoders</code> and never selects a hardware encoder, so run the validator and restart the daemon before you expect a hardware encoder to be chosen automatically.</p><h2 id="list-available-encoders-over-the-api" tabindex="-1">List available encoders over the API <a class="header-anchor" href="#list-available-encoders-over-the-api" aria-label="Permalink to &quot;List available encoders over the API&quot;">​</a></h2><p><code>GET /api/encoders</code> returns the validated encoders the UI offers, split into <code>video_encoders</code> and <code>audio_encoders</code> with a <code>count</code>. It needs validation data: if you haven&#39;t run the validator, it returns <code>400</code> telling you to validate first.</p><p>The video list is exactly the encoders that passed validation. Each entry carries an <code>hwaccel</code> flag set by a name heuristic: an encoder name containing <code>lib</code> is treated as software, anything else as hardware-accelerated. The audio list is hardcoded, not validated: <code>aac</code>, <code>libopus</code>, <code>libmp3lame</code>, and <code>ac3</code>, in that order, all reported as software.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> videonode:videonode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:8090/api/encoders</span></span></code></pre></div><h2 id="set-the-codec-for-a-stream" tabindex="-1">Set the codec for a stream <a class="header-anchor" href="#set-the-codec-for-a-stream" aria-label="Permalink to &quot;Set the codec for a stream&quot;">​</a></h2><p>In the UI, open the stream you want to edit (or create a new one) and set <strong>Codec</strong> to <code>H.264</code> or <code>H.265</code>. VideoNode resolves the logical codec to the best available concrete encoder from the validation results above.</p><p>To do it via the API, see the <code>POST /api/streams</code> and <code>PATCH /api/streams/{stream_id}</code> operations in <a href="./../reference/rest-api">REST API</a>.</p><h2 id="pin-a-specific-encoder" tabindex="-1">Pin a specific encoder <a class="header-anchor" href="#pin-a-specific-encoder" aria-label="Permalink to &quot;Pin a specific encoder&quot;">​</a></h2><p>The stream form has a <strong>Custom encoder args</strong> field, an escape hatch that&#39;s spliced verbatim into the ffmpeg command and overrides codec/bitrate when set. Use it only when the auto-selected encoder doesn&#39;t meet your requirements. Example value:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>-c:v h264_vaapi -profile:v high -b:v 8M -g 60 -f rtsp rtsp://localhost:8554/cam-lobby</span></span></code></pre></div><p>Custom args replace the entire encoder side of the command. VideoNode supplies only the ffmpeg input flags; everything from <code>-c:v</code> through the output target is yours, including the RTSP publish. To keep the stream reachable over RTSP/SRT/WebRTC, end your args with <code>-f rtsp rtsp://localhost:8554/&lt;stream_id&gt;</code>. Without that, the encoder runs but publishes nowhere.</p><p>In a config file, this is the <code>custom_encoder_args</code> field under <code>[streams.&lt;stream_id&gt;.encoder]</code> in <code>streams.toml</code>.</p>`,32)])])}const m=a(s,[["render",r]]);export{u as __pageData,m as default};
